{
  "name": "opencode-fast-apply",
  "version": "2.2.3",
  "description": "OpenCode plugin for Fast Apply - High-performance code editing with OpenAI-compatible APIs (LM Studio, Ollama)",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "npm run build"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.1.6",
    "diff": "^8.0.2"
  },
  "devDependencies": {
    "@types/diff": "^7.0.2",
    "@types/node": "^20.0.0",
    "typescript": "^5.0.0"
  },
  "keywords": [
    "opencode",
    "plugin",
    "fast-apply",
    "code-editing",
    "openai",
    "lm-studio",
    "ollama",
    "ai",
    "code-assistant",
    "llm"
  ],
  "author": "tickernelz",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/tickernelz/opencode-fast-apply.git"
  },
  "bugs": {
    "url": "https://github.com/tickernelz/opencode-fast-apply/issues"
  },
  "homepage": "https://github.com/tickernelz/opencode-fast-apply#readme",
  "license": "MIT",
  "engines": {
    "node": ">=18.0.0"
  }
}
